import numpy as np

def cashflows(perf, terms):
    n_paths = perf.shape[0]
    n_dates = len(terms["observation_dates"])
    cash = np.zeros((n_paths, n_dates), dtype=float)
    alive = np.ones(n_paths, dtype=bool)
    notional = float(terms.get("notional", 1000.0))
    final_idx = int(terms.get("final_index", n_dates - 1))
    autocall = terms.get("autocall")
    coupon = terms.get("coupon")
    downside = terms.get("downside", {}) or {}

    unpaid = None
    if coupon is not None and coupon.get("memory", False):
        unpaid = np.zeros(n_paths, dtype=float)

    for k in range(n_dates):
        if perf.ndim == 3:
            obs_slice = perf[:, k, :]
            if obs_slice.shape[1] == 1:
                obs_perf = obs_slice[:, 0]
            else:
                obs_perf = np.min(obs_slice, axis=1)
        elif perf.ndim == 2:
            obs_perf = perf[:, k]
        else:
            obs_perf = perf

        if coupon is not None:
            amounts = coupon.get("amounts", [])
            amt = amounts[k] if k < len(amounts) else None
            if amt is not None and np.any(alive):
                barrier = float(coupon.get("barrier", 0.0))
                cond_c = obs_perf >= barrier
                is_mem = bool(coupon.get("memory", False))
                if not is_mem:
                    eligible = alive & cond_c
                    if np.any(eligible):
                        cash[eligible, k] += float(amt)
                else:
                    eligible = alive & cond_c
                    if np.any(eligible):
                        cash[eligible, k] += float(amt) + unpaid[eligible]
                        unpaid[eligible] = 0.0
                    not_elig = alive & (~cond_c)
                    if np.any(not_elig):
                        unpaid[not_elig] += float(amt)

        if autocall is not None:
            call_amounts = autocall.get("call_amounts", [])
            amt_call = call_amounts[k] if k < len(call_amounts) else None
            if amt_call is not None and np.any(alive):
                trigger = float(autocall.get("trigger", 0.0))
                cond_a = obs_perf >= trigger
                to_call = alive & cond_a
                if np.any(to_call):
                    cash[to_call, k] += float(amt_call)
                    alive[to_call] = False

    if np.any(alive):
        if perf.ndim == 3:
            final_slice = perf[:, final_idx, :]
            if final_slice.shape[1] == 1:
                final_perf = final_slice[:, 0]
            else:
                final_perf = np.min(final_slice, axis=1)
        elif perf.ndim == 2:
            final_perf = perf[:, final_idx]
        else:
            final_perf = perf
        final_perf = np.asarray(final_perf, dtype=float)

        uf = terms.get("unsupported_features", [])
        has_digital = False
        for f in uf:
            if "Digital" in f or "digital" in f.lower():
                has_digital = True
                break

        if has_digital:
            digital_return = 0.09
            buffer_level = float(downside.get("level", 0.9)) if downside else 0.9
            gearing = float(downside.get("gearing", 1.11111)) if downside else 1.11111
            payment = np.where(final_perf >= buffer_level, notional * (1.0 + digital_return), notional * (1.0 + (final_perf - buffer_level) * gearing))
            payment = np.maximum(payment, 0.0)
            cash[alive, final_idx] += payment[alive]
        else:
            kind = downside.get("kind") if downside else None
            level = float(downside.get("level", 0.0)) if downside else 0.0
            gear = float(downside.get("gearing", 1.0)) if downside else 1.0
            upside = terms.get("upside")
            if upside is not None:
                lev = float(upside.get("leverage", 1.0))
                cap = upside.get("cap")
                upside_ret = np.maximum(0.0, final_perf - 1.0) * lev
                if cap is not None:
                    upside_ret = np.minimum(upside_ret, float(cap))
            else:
                upside_ret = np.zeros_like(final_perf, dtype=float)
            if kind == "buffer":
                payoff = np.where(final_perf >= level, notional * (1.0 + upside_ret), notional * (1.0 + (final_perf - level) * gear))
            elif kind == "barrier":
                payoff = np.where(final_perf >= level, notional * (1.0 + upside_ret), notional * final_perf * gear)
            else:
                payoff = notional * (1.0 + upside_ret)
            payoff = np.maximum(payoff, 0.0)
            cash[alive, final_idx] += payoff[alive]

    return cash
